def _find_parametrized_scope(argnames, arg2fixturedefs, indirect):
    """Find the most appropriate scope for a parametrized call based on its arguments.

    When there's at least one direct argument, always use "function" scope.

    When a test function is parametrized and all its arguments are indirect
    (e.g. fixtures), return the most narrow scope based on the fixtures used.

    Related to issue #1832, based on code posted by @Kingdread.
    """
    from _pytest.fixtures import scopes

    if isinstance(indirect, (list, tuple)):
        all_arguments_are_fixtures = len(indirect) == len(argnames)
    else:
        all_arguments_are_fixtures = bool(indirect)

    if all_arguments_are_fixtures:
        fixturedefs = arg2fixturedefs or {}
        used_scopes = [
            fixturedef[0].scope
            for name, fixturedef in fixturedefs.items()
            if name in argnames
        ]
        if used_scopes:
            # Takes the most narrow scope from used fixtures
            for scope in reversed(scopes):
                if scope in used_scopes:
                    return scope

    return "function"

def resolve_fixture_function(fixturedef, request):
    """Gets the actual callable that can be called to obtain the fixture value, dealing with unittest-specific
    instances and bound methods.
    """
    fixturefunc = fixturedef.func
    if fixturedef.unittest:
        if request.instance is not None:
            # bind the unbound method to the TestCase instance
            fixturefunc = fixturedef.func.__get__(request.instance)
    else:
        # the fixture function needs to be bound to the actual
        # request.instance so that code working with "fixturedef" behaves
        # as expected.
        if request.instance is not None:
            fixturefunc = getimfunc(fixturedef.func)
            if fixturefunc != fixturedef.func:
                fixturefunc = fixturefunc.__get__(request.instance)
    return fixturefunc

def test_func_closure_scopes_reordered(self, testdir):
    """Test ensures that fixtures are ordered by scope regardless of the order of the parameters, although
    fixtures of same scope keep the declared order
    """
    testdir.makepyfile(
        """
        import pytest

        @pytest.fixture(scope='session')
        def s1(): pass

        @pytest.fixture(scope='module')
        def m1(): pass

        @pytest.fixture(scope='function')
        def f1(): pass

        @pytest.fixture(scope='function')
        def f2(): pass

        class Test:

            @pytest.fixture(scope='class')
            def c1(cls): pass

            def test_func(self, f2, f1, c1, m1, s1):
                pass
    """
    )
    items, _ = testdir.inline_genitems()
    request = FixtureRequest(items[0])
    assert request.fixturenames == "s1 m1 c1 f2 f1".split()
